import spidev
import picamera2
import adafruit_mcp3008.MCP3008
import adafruit_mcp3008.util
import adafruit_mcp3008.constants
import time
import signal
import logging

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class LoadCellReader:
    def __init__(self, device_path):
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(device_path, 0, max_speed_hz=50000, mode=0b00, bits_per_word=8)
            self.spi.mode = 0b00
            self.spi.max_speed_hz = 50000
            self.spi.bits_per_word = 8
            self.mcp3008 = adafruit_mcp3008.MCP3008.MCP3008(self.spi)
        except (OSError, IOError) as e:
            logger.error(f"Failed to open SPI device: {e}")
            raise

    def read_raw_data(self):
        try:
            self.spi.write(b'\x00\x00\x00')  # Send the documented three-byte command sequence
            response = self.spi.read(3)
            return (response[1] & adafruit_mcp3008.constants.MCP3008.MCP3008_DEFAULT_DATA_MASK) << 8 | response[2]
        except (OSError, IOError) as e:
            logger.error(f"Failed to read data: {e}")
            return None

    def convert_to_weight(self, raw_data):
        return raw_data * 0.01  # Assuming 0.01g per unit

    def close(self):
        try:
            self.spi.close()
        except (OSError, IOError) as e:
            logger.error(f"Failed to close SPI device: {e}")

def signal_handler(sig, frame):
    logger.info("Stopping program")
    reader.close()
    exit(0)

def main():
    reader = LoadCellReader('/dev/spidev0.0')
    try:
        while True:
            raw_data = reader.read_raw_data()
            if raw_data is not None:
                weight = reader.convert_to_weight(raw_data)
                logger.info(f"Weight: {weight:.2f} kg")
            time.sleep(0.5)
    except KeyboardInterrupt:
        logger.info("Stopping program")
    except Exception as e:
        logger.error(f"Fatal error: {e}")
    finally:
        reader.close()
        logger.info("Shutting down")

if __name__ == "__main__":
    signal.signal(signal.SIGTERM, signal_handler)
    main()

import logging
import time
import threading
from gpiozero import CpuCore
from picamera2 import PiCamera
from adafruit_ads1x15.ads1015 import ADS1015
from adafruit_ads1x15.analog_in import AnalogIn
from paho.mqtt.client import MQTTClient

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class ADS1015Controller:
    def __init__(self, address=0x49, busnum=1, debug=False):
        self.address = address
        self.busnum = busnum
        self.debug = debug
        self.ads1015 = None
        self.last_conversion_results = None
        self.is_running = False

    def _i2c_init(self):
        try:
            self.ads1015 = ADS1015(address=self.address, busnum=self.busnum)
            if self.debug:
                logger.info("ADS1015 I2C bus initialized")
        except IOError as e:
            logger.error(f"Error initializing ADS1015 I2C bus: {e}")

    def _i2c_close(self):
        try:
            self.ads1015 = None
            if self.debug:
                logger.info("ADS1015 I2C bus closed")
        except AttributeError:
            pass

    def read_adc_single_ended(self, channel=0, pga=6144, sps=250):
        if not self.ads1015:
            self._i2c_init()
        try:
            analog_in = AnalogIn(self.ads1015, channel)
            result = analog_in.value * (pga / 4096)
            if self.debug:
                logger.info(f"ADC single-ended read: {result}")
            return int(result)
        except AttributeError as e:
            logger.error(f"Error reading ADC single-ended: {e}")
            return None
        finally:
            self._i2c_close()

    def start_continuous_conversion(self, channel=0, pga=6144, sps=250):
        if not self.ads1015:
            self._i2c_init()
        try:
            self.ads1015.start_continuous_conversion(channel, pga, sps)
            self.is_running = True
            if self.debug:
                logger.info("Continuous conversion started")
        except IOError as e:
            logger.error(f"Error starting continuous conversion: {e}")
        finally:
            self._i2c_close()

    def get_last_conversion_results(self):
        if not self.ads1015:
            self._i2c_init()
        try:
            if self.is_running:
                results = self.ads1015.get_last_conversion_results()
                if self.debug:
                    logger.info(f"Last conversion results: {results}")
                return results
            else:
                return None
        except AttributeError as e:
            logger.error(f"Error getting last conversion results: {e}")
            return None
        finally:
            self._i2c_close()

    def start_single_ended_comparator(self, channel=0, threshold_high=2047, threshold_low=0, pga=6144, sps=250, active_low=True, traditional_mode=True, latching=False, num_readings=1):
        if not self.ads1015:
            self._i2c_init()
        try:
            self.ads1015.config_single_ended_comparator(channel, threshold_high, threshold_low, active_low, traditional_mode, latching, num_readings)
            if self.debug:
                logger.info("Comparator started")
        except IOError as e:
            logger.error(f"Error starting comparator: {e}")
        finally:
            self._i2c_close()

def main():
    # Set up I2C bus
    try:
        import smbus
        i2c = smbus.SMBus(1)
    except ImportError:
        logger.error("Error importing SMBus library")
        return

    # Set up MQTT client
    client = MQTTClient("ADS1015_MQTT", "localhost", 1883)
    client.connect()

    # Create ADS1015 controller
    ads1015_controller = ADS1015Controller(debug=True)

    # Start continuous conversion
    ads1015_controller.start_continuous_conversion()

    # Read ADC single-ended
    result = ads1015_controller.read_adc_single_ended()
    print(result)

    # Get last conversion results
    results = ads1015_controller.get_last_conversion_results()
    print(results)

    # Start comparator
    ads1015_controller.start_single_ended_comparator()

    # Read ADC single-ended again
    result = ads1015_controller.read_adc_single_ended()
    print(result)

    # Close I2C bus
    i2c.close()

    # Disconnect MQTT client
    client.disconnect()

if __name__ == "__main__":
    main()

