from adafruit_mcp3008 import MCP3008
from adafruit_mcp3008 import SPI
from paho.mqtt.client import MQTTClient

class GasSensor:
    def __init__(self, spi_bus=0, cs_pin=0):
        self.spi_bus = spidev.SpiDev()
        self.spi_bus.open(spi_bus, cs_pin)
        self.mcp3008 = MCP3008(self.spi_bus)

    def read_raw(self):
        try:
            raw_value = self.mcp3008.read(0)
            return raw_value
        except OSError as e:
            print(f"SPI bus error: {e}")
            return None

    def convert_to_ppm(self, raw_value):
        return int((raw_value / 1023) * 500)

    def get_alert_level(self, ppm):
        if ppm < 150:
            return "safe"
        elif ppm < 400:
            return "warning"
        else:
            return "danger"

    def run(self):
        client = MQTTClient("gas_sensor")
        client.connect("localhost", 1883)

        while True:
            raw_value = self.read_raw()
            if raw_value is not None:
                ppm = self.convert_to_ppm(raw_value)
                alert_level = self.get_alert_level(ppm)
                print(f"PPM: {ppm}, Alert Level: {alert_level}")
                client.publish("gas_sensor/level", alert_level)
            time.sleep(0.5)

            # Handle SIGINT and SIGTERM signals
            import signal
            def signal_handler(sig, frame):
                print("SIGINT or SIGTERM received, shutting down")
                client.disconnect()
                self.spi_bus.close()
                exit(0)
            signal.signal(signal.SIGINT, signal_handler)
            signal.signal(signal.SIGTERM, signal_handler)

if __name__ == "__main__":
    gas_sensor = GasSensor()
    gas_sensor.run()

