    exit(1)

# Set up directory
try:
    os.makedirs('/home/pi/thermal_logs', exist_ok=True)
except Exception as e:
    logging.error(f"Directory creation failed: {e}")
    exit(1)

# Set up CSV file
try:
    with open('/home/pi/thermal_logs/thermal_data.csv', 'w', newline='') as csvfile:
        writer = csv.writer(csvfile)
        writer.writerow(['timestamp', 'average_temperature', 'temperature_map'])
except Exception as e:
    logging.error(f"CSV file creation failed: {e}")
    exit(1)

# Set up plot
try:
    plt.ion()
    plt.style.use('seaborn-colorblind10')
    plt.title('Thermal Map')
    plt.xlabel('X')
    plt.ylabel('Y')
    plt.xticks([])
    plt.yticks([])
except Exception as e:
    logging.error(f"Plot setup failed: {e}")
    exit(1)

# Main loop
try:
    while True:
        # Read sensor data
        try:
            sensor.read()
        except CPUTimeoutError:
            logging.warning("Sensor read timed out")
            continue
        except Exception as e:
            logging.error(f"Sensor read failed: {e}")
            continue

        # Read camera data
        try:
            camera.capture('thermal_image.jpg', format='bgr', use_video_port=True)
        except Exception as e:
            logging.error(f"Camera capture failed: {e}")
            continue

        # Convert image to grayscale
        try:
            img = cv2.imread('thermal_image.jpg')
            gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
        except Exception as e:
            logging.error(f"Image conversion failed: {e}")
            continue

        # Compute average temperature
        try:
            avg_temp = np.mean(gray)
        except Exception as e:
            logging.error(f"Average temperature computation failed: {e}")
            continue

        # Generate heat map
        try:
            plt.imshow(gray, cmap='jet')
            plt.draw()
            plt.pause(0.01)
        except Exception as e:
            logging.error(f"Heat map generation failed: {e}")
            continue

        # Save image
        try:
            plt.savefig('/home/pi/thermal_logs/thermal_image_{}.png'.format(datetime.datetime.now().strftime('%Y%m%d_%H%M%S')))
        except Exception as e:
            logging.error(f"Image saving failed: {e}")
            continue

        # Append to log
        try:
            logging.info(f"Timestamp: {datetime.datetime.now()}")
            logging.info(f"Average temperature: {avg_temp}")
            if avg_temp > 70.0:
                logging.warning("Average temperature exceeds 70.0°C")
        except Exception as e:
            logging.error(f"Log append failed: {e}")
            continue

        # Append to CSV
        try:
            with open('/home/pi/thermal_logs/thermal_data.csv', 'a', newline='') as csvfile:
                writer = csv.writer(csvfile)
                writer.writerow([datetime.datetime.now(), avg_temp, gray.flatten()])
        except Exception as e:
            logging.error(f"CSV append failed: {e}")
            continue

        # Publish to MQTT
        try:
            client.publish('thermal/temperature', str(avg_temp))
        except Exception as e:
            logging.error(f"MQTT publish failed: {e}")
            continue

        # Sleep for 1 second
        time.sleep(1)

except KeyboardInterrupt:
    # Release resources
    try:
        plt.close()
    except Exception as e:
        logging.error(f"Plot close failed: {e}")
    finally:
        try:
            os.remove('/home/pi/thermal_logs/thermal_image_*.png')
        except Exception as e:
            logging.error(f"Image removal failed: {e}")
        try:
            os.remove('/home/pi/thermal_logs/thermal_data.csv')
        except Exception as e:
            logging.error(f"CSV removal failed: {e}")
        try:
            client.disconnect()
        except Exception as e:
            logging.error(f"MQTT disconnect failed: {e}")
        try:
            sensor.close()
        except Exception as e:
            logging.error(f"Sensor close failed: {e}")
        try:
            i2c.close()
        except Exception as e:
            logging.error(f"I2C close failed: {e}")
        try:
            camera.close()
