import paho.mqtt.client as mqtt
import logging

# Set up logging
logging.basicConfig(format='%(asctime)s - %(levelname)s - %(message)s', level=logging.INFO)
logger = logging.getLogger(__name__)

# Constants
LOW_LIGHT_THRESHOLD = 300
HIGH_TEMP_THRESHOLD = 35
HIGH_PI_TEMP_THRESHOLD = 75
DEFAULT_VOLTAGE = 10.0
DEFAULT_CURRENT = 0.5
DEFAULT_TEMPERATURE = 20

class LightSensor:
    def __init__(self, pin):
        self.pin = pin
        self.gpio = gpiozero.Gpio(self.pin)
        self.gpio.direction = gpiozero.Direction.IN

    def read(self):
        try:
            value = self.gpio.value
            if value == 0:
                return 0
            else:
                return 1000
        except Exception as e:
            logger.warning(f"Error reading light sensor: {e}")
            return 0

class TemperatureSensor:
    def __init__(self, pin):
