from adafruit_circuitpython_mcp3008 import MCP3008
from adafruit_circuitpython_smbus import SMBus
from paho.mqtt.client import MQTTClient
import logging

# Define a custom exception for driver connection issues
class DriverConnectionError(Exception):
    pass

class OutputPin:
    def __init__(self, pin_number: int, initial_value: int) -> None:
        if not 0 <= pin_number <= 31:
            raise ValueError("Invalid pin number. Must be between 0 and 31.")
        if initial_value not in [0, 1]:
            raise ValueError("Invalid initial value. Must be 0 or 1.")

        try:
            self.gpio = CpuGPIO(pin_number)
            self.mcp3008 = MCP3008()
            self.mqtt_client = MQTTClient()
            self.mqtt_client.connect("localhost", 1883)
            self.mqtt_client.publish("output_pin", str(pin_number))
        except Exception as e:
            raise DriverConnectionError("Failed to connect to driver daemon") from e

    def set_value(self, value: int) -> None:
        if value not in [0, 1]:
            raise ValueError("Invalid value. Must be 0 or 1.")
        try:
            if value == 0:
                self.gpio.output(0)
                self.mcp3008.write(0)
                self.mqtt_client.publish("output_pin", "0")
            else:
                self.gpio.output(1)
                self.mcp3008.write(1)
                self.mqtt_client.publish("output_pin", "1")
        except Exception as e:
            logging.error(f"Failed to set value: {e}")

    def shutdown(self) -> None:
        try:
            self.gpio.input(0)
            self.mcp3008.write(0)
            self.mqtt_client.disconnect()
        except Exception as e:
            logging.error(f"Failed to shutdown: {e}")

if __name__ == "__main__":
    pin = OutputPin(17, 1)
    for _ in range(5):
        pin.set_value(1)
        time.sleep(0.5)
    pin.shutdown()

