import time
import threading
from gpiozero import RotaryEncoder
from picamera2 import PiCamera
from adafruit_circuitpython_mcp3008 import MCP3008
from paho.mqtt.client import MQTTClient

class RotaryEncoder:
    def __init__(self, clk_pin, dt_pin, callback=None, debounce=0.005):
        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback
        self.debounce = debounce
        self.clk_state = None
        self.dt_state = None
        self.steps = 0
        self.lock = threading.Lock()
        self.encoder = RotaryEncoder(clk_pin, dt_pin, pull_up=True, pull_down=True)
        self.encoder.callback = self._callback

    def _callback(self, steps):
        with self.lock:
            self.steps = steps
            if self.callback:
                try:
                    self.callback(steps)
                except Exception as e:
                    print(f"Error in callback: {e}")

    def cleanup(self):
        self.encoder.close()
        self.encoder = None

    def run(self):
        self.encoder.start()
        while True:
            try:
                self.encoder.wait_for_edge(self.clk_pin, timeout=self.debounce)
                with self.lock:
                    if self.clk_state is None:
                        self.clk_state = self.encoder.read(self.dt_pin)
                    elif self.clk_state == 0 and self.dt_state == 1:
                        self.steps += 1
                    elif self.clk_state == 1 and self.dt_state == 0:
                        self.steps -= 1
                    self.dt_state = self.encoder.read(self.dt_pin)
                    if self.callback:
                        self._callback(self.steps)
            except KeyboardInterrupt:
                self.cleanup()
                break
            except Exception as e:
                print(f"Error: {e}")
                self.cleanup()
                break

def main():
    try:
        encoder = RotaryEncoder(17, 18, callback=lambda steps: print(f"Rotated {steps} steps"))
        encoder.run()
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()

