# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Define signal handler
def signal_handler(sig, frame):
    logger.info("Received signal, exiting...")
    try:
        # Cleanup GPIO
        gpio.zero.cleanup()
    except AttributeError:
        pass
    finally:
        # Cleanup MQTT
        try:
            client.disconnect()
        except AttributeError:
            pass
    sys.exit(0)

# Define get_raspi_model function
def get_raspi_model():
    # Map board revision code to model name
    if sys.platform == "armv7l":
        if hasattr(sys, 'machine'):
            if sys.machine == 'armv7l':
                return "Raspberry Pi 3"
            elif sys.machine == 'armv7l-bcm283p':
                return "Raspberry Pi 3 Model B"
            elif sys.machine == 'armv7l-bcm283p2':
                return "Raspberry Pi 3 Model B+"
            elif sys.machine == 'armv7l-bcm283p3':
                return "Raspberry Pi 4"
            elif sys.machine == 'armv7l-bcm283p4':
                return "Raspberry Pi 4"
            elif sys.machine == 'armv8l':
                return "Raspberry Pi 4"
        else:
            return "Unknown"
    else:
        return "Unknown"

# Define get_gpio_num function
def get_gpio_num():
    # Return GPIO count based on board revision
    if hasattr(sys, 'machine'):
        if sys.machine == 'armv7l':
            return 17
        elif sys.machine == 'armv7l-bcm283p':
            return 26
        elif sys.machine == 'armv7l-bcm283p2':
            return 26
        elif sys.machine == 'armv7l-bcm283p3':
