    model = get_raspi_model()
    logger.info(f"Detected model: {model}")

    # Detect GPIO count
    gpio_count = get_gpio_num()
    logger.info(f"GPIO count: {gpio_count}")

    # Print "Monitoring..."
    logger.info("Monitoring...")

    # Create GPIO object
    try:
        gpio = CircuitPythonGPIOZero(gpio_ch)
    except RuntimeError as e:
        logger.error(f"Error creating GPIO object: {e}")
        sys.exit(1)

    # Configure GPIO pins as debounced inputs
    for pin in gpio_ch:
        gpio.setup(pin, gpio.IN, pull_up_down=gpio.PULL_UP, debounce=200)

    # Create MQTT client
    try:
        client = MQTTClient()
    except AttributeError:
        logger.error("Error creating MQTT client")
        sys.exit(1)

    # Register callback for state-change events
    def callback(client, userdata, message):
        logger.info(f"Received message: {message.payload.decode()}")

    client.on_connect = callback

    # Connect to MQTT broker
    try:
        client.connect("localhost", 1883)
    except MQTTConnectError as e:
        logger.error(f"Error connecting to MQTT broker: {e}")
        sys.exit(1)

    # Enter time.sleep loop
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        logger.info("Received interrupt, exiting...")
    except SystemExit:
        logger.info("Received SystemExit, exiting...")
    except Exception as e:
        logger.error(f"Error: {e}")

    # Cleanup MQTT
    try:
        client.disconnect()
    except AttributeError:
        pass

    # Cleanup GPIO
    try:
        gpio.zero.cleanup()
    except AttributeError:
        pass

# Install signal handler
