    logging.error(f"Failed to initialize MQTT client: {e}")
    exit(1)

# Set up MCP3008 ADC
try:
    adc = MCP3008(0)
except Exception as e:
    logging.error(f"Failed to initialize MCP3008 ADC: {e}")
    exit(1)

# Set up signal handler for KeyboardInterrupt
def signal_handler(sig, frame):
    logging.info("Program stopped. LED is OFF.")
    try:
        led.off()
    except Exception as e:
        logging.error(f"Failed to turn off LED: {e}")
    finally:
        try:
            camera.close()
        except Exception as e:
            logging.error(f"Failed to close camera: {e}")
        try:
            client.disconnect()
        except Exception as e:
            logging.error(f"Failed to disconnect MQTT client: {e}")
        exit(0)

signal.signal(signal.SIGINT, signal_handler)

try:
    while True:
        led.on()
        logging.info("LED is ON")
        time.sleep(1)
        led.off()
        logging.info("LED is OFF")
        time.sleep(1)
except KeyboardInterrupt:
    logging.info("Program stopped. LED is OFF.")
    try:
        led.off()
    except Exception as e:
        logging.error(f"Failed to turn off LED: {e}")
finally:
    try:
        camera.close()
    except Exception as e:
        logging.error(f"Failed to close camera: {e}")
    try:
        client.disconnect()
    except Exception as e:
        logging.error(f"Failed to disconnect MQTT client: {e}")
