import os
import logging
import time
import threading
from gpiozero import LED
from picamera2 import PiCamera
from adafruit_circuitpython_mcp3008 import MCP3008
from paho.mqtt.client import MQTTClient

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Set up GPIO
try:
    led = LED(18)
except RuntimeError:
    logger.error("Failed to initialize LED on GPIO 18")
    led = None

# Set up camera
try:
    camera = PiCamera()
except RuntimeError:
    logger.error("Failed to initialize camera")
    camera = None

# Set up MCP3008 ADC
try:
    adc = MCP3008()
except RuntimeError:
    logger.error("Failed to initialize ADC")
    adc = None

# Set up MQTT client
try:
    mqtt_client = MQTTClient()
except RuntimeError:
    logger.error("Failed to initialize MQTT client")
    mqtt_client = None

# Define the grid dimensions
GRID_SIZE = 5

# Define the occupancy grid
occupancy_grid = [[0 for _ in range(GRID_SIZE)] for _ in range(GRID_SIZE)]

# Define the start and end cells
start_cell = (0, 0)
end_cell = (4, 4)

# Define the search function
def bfs_search(grid, start, end):
    queue = [(start, [start])]
    visited = set()
    while queue:
        (x, y), path = queue.pop(0)
        if (x, y) == end:
            return len(path) - 1
        if (x, y) in visited:
            continue
        visited.add((x, y))
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < GRID_SIZE and 0 <= ny < GRID_SIZE and occupancy_grid[nx][ny] == 0:
                queue.append(((nx, ny), path + [(nx, ny)]))
    return -1

# Define the main function
def main():
    global led, camera, adc, mqtt_client

    # Validate grid dimensions
    if GRID_SIZE != 5:
        logger.error("Invalid grid size. Expected 5x5.")
        return

    # Initialize occupancy grid
    occupancy_grid[0][0] = 1  # Set start cell as obstacle
    occupancy_grid[4][4] = 1  # Set end cell as obstacle

    # Perform BFS search
    try:
        path_length = bfs_search(occupancy_grid, start_cell, end_cell)
        if path_length == -1:
            logger.error("No path found.")
            led.blink(3, 0.5)
        else:
            logger.info(f"Path length: {path_length}")
            led.on()
            time.sleep(2)
            led.off()
    except Exception as e:
        logger.error(f"Error: {e}")
        led.blink(3, 0.5)

    # Release resources
    if led:
        led.off()
    if camera:
        camera.close()
    if adc:
        adc.close()
    if mqtt_client:
        mqtt_client.disconnect()

# Run the main function
if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        logger.info("Received KeyboardInterrupt. Cleaning up resources...")
        if led:
            led.off()
        if camera:
            camera.close()
        if adc:
            adc.close()
        if mqtt_client:
            mqtt_client.disconnect()
    except Exception as e:
        logger.error(f"Error: {e}")
        if led:
            led.off()
        if camera:
            camera.close()
        if adc:
            adc.close()
        if mqtt_client:
            mqtt_client.disconnect()

