class PIRMotionSensor:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)
        self.logger.addHandler(logging.StreamHandler())
        self.logger.info("Initializing PIR motion sensor")

        self.pi = None
        self.mcp3008 = None
        self.camera = None
        self.mqtt_client = None

        self.pi = self._setup_pi()
        self.mcp3008 = self._setup_mcp3008()
        self.camera = self._setup_camera()
        self.mqtt_client = self._setup_mqtt()

        self.visitors = 0
        self.last_motion_time = time.time()
        self.debounce_window = 200
        self.debounce_count = 0
        self.debounce_timeout = 30
        self.debounce_timeout_count = 0
        self.debounce_timeout_start_time = 0
        self.debounce_timeout_end_time = 0
        self.debounce_timeout_reset = False

        self._setup_signal_handlers()

    def _setup_pi(self):
        try:
            import RPi.GPIO as GPIO
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(23, GPIO.IN)
            return GPIO
        except Exception as e:
            self.logger.error(f"Failed to set up GPIO: {e}")
            return None

    def _setup_mcp3008(self):
        try:
            from adafruit_mcp3008 import MCP3008
            return MCP3008()
        except Exception as e:
            self.logger.error(f"Failed to set up MCP3008: {e}")
            return None

    def _setup_camera(self):
        try:
            from picamera2 import PiCamera
            return PiCamera()
        except Exception as e:
            self.logger.error(f"Failed to set up camera: {e}")
            return None

    def _setup_mqtt(self):
        try:
            from paho.mqtt.client import MQTTClient
            return MQTTClient()
        except Exception as e:
            self.logger.error(f"Failed to set up MQTT: {e}")
            return None

    def _setup_signal_handlers(self):
        def signal_handler(sig, frame):
            self._clean_up()
            raise KeyboardInterrupt

        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)

    def _read_mcp3008(self):
        try:
            return self.mcp3008.read(0)
        except Exception as e:
            self.logger.error(f"Failed to read MCP3008: {e}")
            return None

    def _read_pi(self):
        try:
            return self.pi.input(23)
        except CPUTimeoutError:
            return None
        except Exception as e:
            self.logger.error(f"Failed to read GPIO: {e}")
            return None

    def _debounce(self, value):
        if value is None:
            return False
        if self.debounce_count == 0:
            self.debounce_count = 1
            self.debounce_timeout_count = 0
            self.debounce_timeout_start_time = time.time()
            self.debounce_timeout_end_time = 0
            self.debounce_timeout_reset = False
        elif self.debounce_count < self.debounce_window:
            self.debounce_count += 1
            if time.time() - self.debounce_timeout_start_time > self.debounce_timeout:
                self.debounce_timeout_reset = True
        else:
            self.debounce_count = 0
            self.debounce_timeout_count += 1
            if self.debounce_timeout_reset:
                self.debounce_timeout_end_time = time.time()
                self.debounce_timeout_reset = False
        return self.debounce_count < self.debounce_window

    def _poll(self):
        try:
            value = self._read_pi()
            if value is not None and self._debounce(value):
                self.visitors += 1
                self.last_motion_time = time.time()
                self.logger.info("Motion detected")
            elif self.debounce_timeout_count >= self.debounce_timeout:
                self.logger.info("No motion detected for 30 seconds")
                self.visitors = 0
                self.debounce_timeout_count = 0
                self.debounce_timeout_reset = False
        except Exception as e:
            self.logger.error(f"Failed to poll sensor: {e}")

    def _clean_up(self):
        try:
            if self.pi is not None:
                self.pi.cleanup()
            if self.mcp3008 is not None:
                self.mcp3008.close()
            if self.camera is not None:
                self.camera.close()
            if self.mqtt_client is not None:
                self.mqtt_client.disconnect()
            self.logger.info("Cleaned up")
        except Exception as e:
            self.logger.error(f"Failed to clean up: {e}")

    def run(self):
        try:
            while True:
                self._poll()
                if time.time() - self.last_motion_time > 60:
                    self.logger.info(f"Total visitors: {self.visitors}")
                if time.time() - self.debounce_timeout_end_time > 60:
                    self.logger.info(f"Total visitors: {self.visitors}")
                    self._clean_up()
                    break
                time.sleep(10)
        except KeyboardInterrupt:
            self._clean_up()
            raise

if __name__ == "__main__":
    motion_sensor = PIRMotionSensor()
    motion_sensor.run()

