    intents = {
        'pump_on': 'turn the pump on',
        'pump_off': 'turn the pump off',
        'light': 'switch the light',
        'light_toggle': 'toggle the light'
    }
    intent = keyword.casefold(phrase)
    return intent in intents

def drive_pump(state):
    """Drive the nutrient pump"""
    try:
        pump = DigitalOutput(PUMP_PIN)
        if state:
            pump.on()
        else:
