import time
import serial
import threading
import RPi.GPIO as GPIO
import logging

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Set up GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setup(18, GPIO.OUT)

# Set up serial port
try:
    ser = serial.Serial('/dev/ttyUSB0', 9600, timeout=1)
except serial.SerialException as e:
    logger.error(f"Failed to open serial port: {e}")
    exit(1)

def read_radiation_level():
    while True:
        try:
            line = ser.readline()
            if not line:
                continue
            try:
                level = float(line.decode('ascii').strip())
                if level > 50.0:
                    GPIO.output(18, GPIO.HIGH)
                else:
                    GPIO.output(18, GPIO.LOW)
            except ValueError:
                logger.warning("Failed to parse radiation level")
        except KeyboardInterrupt:
            logger.info("Received KeyboardInterrupt, shutting down")
            break
        finally:
            ser.close()
            GPIO.cleanup()
            exit(0)

def main():
    try:
        threading.Thread(target=read_radiation_level).start()
    except Exception as e:
        logger.error(f"Failed to start radiation level reader: {e}")
        GPIO.cleanup()
        exit(1)

if __name__ == "__main__":
    main()

