class ESP8266UART:
    def __init__(self):
        self._uart = None
        self._gpio = CPGpio()
        self._gpio.setup(14, CPGpio.OUT)
        self._gpio.setup(15, CPGpio.IN)
        self._uart = serial.Serial('/dev/ttyUSB0', 115200, timeout=5, bytesize=serial.EIGHTBITS, parity=serial.PARITY_NONE, stopbits=serial.STOPBITS_ONE)
        self._uart.port = self._uart

    def _send_command(self, command, delay=1, max_retries=3):
        try:
            self._uart.write(command.encode())
            time.sleep(delay)
            response = self._read_response()
            if response is not None:
                return response
            for _ in range(max_retries):
                response = self._read_response()
                if response is not None:
                    return response
            return None
        except serial.SerialException as e:
            logging.error(f"Serial error: {e}")
            return None

    def _read_response(self):
        try:
            response = self._uart.readline()
            response = response.decode().strip()
            if response in ["OK", "ERROR", "FAIL"]:
                return response
            else:
                return None
        except serial.SerialException as e:
            logging.error(f"Serial error: {e}")
            return None

    def test_connection(self):
        response = self._send_command("AT\r\n")
        if response is None:
            logging.error("Failed to test connection")
            return False
        return response == "OK"

    def restart(self):
        response = self._send_command("AT+RST\r\n")
        if response is None:
            logging.error("Failed to restart")
            return False
        time.sleep(2)
        response = self._read_response()
        if response is None:
            logging.error("Failed to verify restart")
            return False
        return response == "OK"

    def connect_wifi(self, ssid, password):
        response = self._send_command(f"AT+CWJAP_CUR,\"{ssid}\",\"{password}\",0\r\n")
        if response is None:
            logging.error("Failed to connect to WiFi")
            return False
        return "WIFI GOT IP" in response

    def __del__(self):
        if self._uart is not None:
            self._uart.close()
            self._gpio.cleanup()

def signal_handler(sig, frame):
    logging.info("Received signal, cleaning up resources")
    if hasattr(ESP8266UART, '_uart'):
        ESP8266UART._uart.close()
    if hasattr(ESP8266UART, '_gpio'):
        ESP8266UART._gpio.cleanup()
    exit(0)

signal.signal(signal.SIGINT, signal_handler)

if __name__ == "__main__":
    uart = ESP8266UART()
    if not uart.test_connection():
        logging.error("Failed to test connection")
        exit(1)
    if not uart.restart():
        logging.error("Failed to restart")
        exit(1)
    if not uart.connect_wifi("your_ssid", "your_password"):
        logging.error("Failed to connect to WiFi")
        exit(1)
